"use client";

import { useState, useEffect } from "react";
import { ChevronRight, Check, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { supplierCatalogService, SupplierCatalogOption } from "@/services/supplierCatalogService";
import { SearchableSelect } from "@/components/ui/SearchableSelect";
import type { BusinessTypePublic } from "@/types/businessType";

export interface RecommendationCategory {
  id: number;
  name: string;
  slug: string;
}

export interface RecommendationSubcategory {
  id: number;
  name: string;
  category_id: number;
  slug: string;
}

const apiUrl = (path: string) => {
  const base = process.env.NEXT_PUBLIC_API_BASE_URL || "https://drooopy.com/api";
  return `${base.replace(/\/$/, "")}${path}`;
};

const unwrapList = <T,>(data: unknown, key: string): T[] => {
  if (Array.isArray(data)) return data as T[];
  if (data && typeof data === "object") {
    const record = data as Record<string, unknown>;
    const items = record.items ?? record.results ?? record.data ?? record[key];
    if (Array.isArray(items)) return items as T[];
  }
  return [];
};

const fetchPublicList = async <T,>(urls: string[], key: string) => {
  for (const url of urls) {
    try {
      const response = await fetch(url, { headers: { Accept: "application/json" } });
      if (!response.ok) {
        if (response.status === 404 || response.status === 405) continue;
        return [];
      }
      const data: unknown = await response.json().catch(() => null);
      return unwrapList<T>(data, key);
    } catch {
      continue;
    }
  }
  return [];
};

const MEXICO_COUNTRY_ID = 1;

interface RecommendationsSidebarProps {
  businessTypeId?: number | null;
  businessTypeSlug?: string;
  businessTypes: BusinessTypePublic[];
  selectedIsDirectory?: boolean;
  selectedCategory?: string;
  selectedSubcategory?: string;
  minPrice?: number;
  maxPrice?: number;
  bestRated?: boolean;
  city?: string;
  state?: string;
  onFilterChange: (filters: {
    category?: string;
    subcategory?: string;
    minPrice?: number;
    maxPrice?: number;
    bestRated?: boolean;
    city?: string;
    state?: string;
  }) => void;
  onBusinessTypeChange: (slug: string | null, isDirectory?: boolean) => void;
  onClear?: () => void;
  onClose?: () => void;
  onCatalogLoaded?: (categories: RecommendationCategory[], subcategories: RecommendationSubcategory[]) => void;
}

export function RecommendationsSidebar({
  businessTypeId,
  businessTypeSlug,
  businessTypes,
  selectedIsDirectory,
  selectedCategory,
  selectedSubcategory,
  minPrice,
  maxPrice,
  bestRated,
  city,
  state,
  onFilterChange,
  onBusinessTypeChange,
  onClear,
  onClose,
  onCatalogLoaded,
}: RecommendationsSidebarProps) {
  const [categories, setCategories] = useState<RecommendationCategory[]>([]);
  const [subcategories, setSubcategories] = useState<RecommendationSubcategory[]>([]);
  const [expandedCategory, setExpandedCategory] = useState<string | null>(null);
  const [localMinPrice, setLocalMinPrice] = useState(minPrice?.toString() || "");
  const [localMaxPrice, setLocalMaxPrice] = useState(maxPrice?.toString() || "");
  const [states, setStates] = useState<SupplierCatalogOption[]>([]);
  const [cities, setCities] = useState<SupplierCatalogOption[]>([]);
  const [selectedState, setSelectedState] = useState<SupplierCatalogOption | null>(null);
  const [selectedCity, setSelectedCity] = useState<SupplierCatalogOption | null>(null);
  const [catalogLoading, setCatalogLoading] = useState({ states: false, cities: false });

  useEffect(() => {
    let active = true;

    const fetchData = async () => {
      try {
        if (businessTypeSlug) {
          if (!businessTypeId) {
            setCategories([]);
            setSubcategories([]);
            onCatalogLoaded?.([], []);
            return;
          }

          const response = await fetch(apiUrl(`/business-types/${businessTypeId}/categories`), {
            headers: { Accept: "application/json" },
          });
          if (!response.ok) throw new Error(`Business type catalog failed (${response.status})`);
          const payload: unknown = await response.json();
          const root = payload && typeof payload === "object" ? payload as Record<string, unknown> : {};
          const source = root.data && typeof root.data === "object" && !Array.isArray(root.data)
            ? root.data as Record<string, unknown>
            : root;
          const rawCategories = Array.isArray(source.categories)
            ? source.categories
            : Array.isArray(payload) ? payload : [];
          const scopedCategories: RecommendationCategory[] = [];
          const nestedSubcategories: RecommendationSubcategory[] = [];

          for (const item of rawCategories) {
            if (!item || typeof item !== "object") continue;
            const category = item as Record<string, unknown>;
            const id = Number(category.id);
            const name = typeof category.name === "string" ? category.name : "";
            const slug = typeof category.slug === "string" ? category.slug : "";
            if (!Number.isFinite(id) || !name || !slug) continue;
            scopedCategories.push({ id, name, slug });
            if (Array.isArray(category.subcategories)) {
              for (const value of category.subcategories) {
                if (!value || typeof value !== "object") continue;
                const subcategory = value as Record<string, unknown>;
                const subcategoryId = Number(subcategory.id);
                const subcategoryName = typeof subcategory.name === "string" ? subcategory.name : "";
                const subcategorySlug = typeof subcategory.slug === "string" ? subcategory.slug : "";
                if (Number.isFinite(subcategoryId) && subcategoryName && subcategorySlug) {
                  nestedSubcategories.push({ id: subcategoryId, name: subcategoryName, slug: subcategorySlug, category_id: id });
                }
              }
            }
          }

          const topLevelSubcategories = Array.isArray(source.subcategories)
            ? source.subcategories.flatMap((value): RecommendationSubcategory[] => {
                if (!value || typeof value !== "object") return [];
                const subcategory = value as Record<string, unknown>;
                const id = Number(subcategory.id);
                const categoryId = Number(subcategory.category_id);
                const name = typeof subcategory.name === "string" ? subcategory.name : "";
                const slug = typeof subcategory.slug === "string" ? subcategory.slug : "";
                return Number.isFinite(id) && Number.isFinite(categoryId) && name && slug
                  ? [{ id, category_id: categoryId, name, slug }]
                  : [];
              })
            : [];
          const scopedSubcategories = topLevelSubcategories.length ? topLevelSubcategories : nestedSubcategories;
          if (!active) return;
          setCategories(scopedCategories);
          setSubcategories(scopedSubcategories);
          setExpandedCategory(null);
          onCatalogLoaded?.(scopedCategories, scopedSubcategories);
          return;
        }

        const [catData, subData] = await Promise.all([
          fetchPublicList<RecommendationCategory>(
            [
              "/api/categories/?skip=0&limit=100",
              "/api/backend/categories/?skip=0&limit=100",
              apiUrl("/categories/?skip=0&limit=100"),
            ],
            "categories",
          ),
          fetchPublicList<RecommendationSubcategory>(
            [
              "/api/subcategories/?skip=0&limit=1000",
              "/api/backend/subcategories/?skip=0&limit=1000",
              apiUrl("/subcategories/?skip=0&limit=1000"),
            ],
            "subcategories",
          ),
        ]);
        if (!active) return;
        setCategories(catData);
        setSubcategories(subData);
        onCatalogLoaded?.(catData, subData);
      } catch (error) {
        console.error("Failed to fetch sidebar data", error);
        if (active) {
          setCategories([]);
          setSubcategories([]);
          onCatalogLoaded?.([], []);
        }
      }
    };
    void fetchData();
    return () => { active = false; };
  }, [businessTypeId, businessTypeSlug, onCatalogLoaded]);

  useEffect(() => {
    let active = true;

    const fetchStates = async () => {
      setCatalogLoading((current) => ({ ...current, states: true }));
      try {
        const items = await supplierCatalogService.states(MEXICO_COUNTRY_ID);
        if (active) setStates(items);
      } finally {
        if (active) setCatalogLoading((current) => ({ ...current, states: false }));
      }
    };

    fetchStates();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    if (!selectedState) {
      return;
    }

    let active = true;

    const fetchCities = async () => {
      setCatalogLoading((current) => ({ ...current, cities: true }));
      try {
        const items = await supplierCatalogService.cities(selectedState.id);
        if (active) setCities(items);
      } finally {
        if (active) setCatalogLoading((current) => ({ ...current, cities: false }));
      }
    };

    fetchCities();
    return () => {
      active = false;
    };
  }, [selectedState]);

  const handleCategoryClick = (categorySlug: string) => {
    if (expandedCategory === categorySlug) {
      setExpandedCategory(null);
    } else {
      setExpandedCategory(categorySlug);
    }
    
    // If clicking the category itself, select it and clear subcategory
    if (selectedCategory === categorySlug) {
        onFilterChange({ category: undefined, subcategory: undefined, minPrice, maxPrice, bestRated, city, state });
    } else {
        onFilterChange({ category: categorySlug, subcategory: undefined, minPrice, maxPrice, bestRated, city, state });
    }
  };

  const handleSubcategoryClick = (e: React.MouseEvent, subcategorySlug: string, categorySlug: string) => {
    e.stopPropagation();
    if (selectedSubcategory === subcategorySlug) {
        onFilterChange({ category: categorySlug, subcategory: undefined, minPrice, maxPrice, bestRated, city, state });
    } else {
        onFilterChange({ category: categorySlug, subcategory: subcategorySlug, minPrice, maxPrice, bestRated, city, state });
    }
  };

  const handlePriceApply = () => {
    const min = localMinPrice ? parseFloat(localMinPrice) : undefined;
    const max = localMaxPrice ? parseFloat(localMaxPrice) : undefined;
    onFilterChange({ 
        category: selectedCategory, 
        subcategory: selectedSubcategory, 
        minPrice: min, 
        maxPrice: max,
        bestRated,
        city,
        state
    });
  };

  const handleLocationApply = () => {
    onFilterChange({
        category: selectedCategory,
        subcategory: selectedSubcategory,
        minPrice,
        maxPrice,
        bestRated,
        city: selectedCity?.name,
        state: selectedState?.name
    });
  };

  const handleApplyAll = () => {
    const min = localMinPrice ? parseFloat(localMinPrice) : undefined;
    const max = localMaxPrice ? parseFloat(localMaxPrice) : undefined;
    onFilterChange({
        category: selectedCategory,
        subcategory: selectedSubcategory,
        minPrice: min,
        maxPrice: max,
        bestRated,
        city: selectedCity?.name,
        state: selectedState?.name
    });
  };
  
  const handleClearAll = () => {
      setLocalMinPrice("");
      setLocalMaxPrice("");
      setSelectedState(null);
      setSelectedCity(null);
      setCities([]);
      setExpandedCategory(null);
      if (onClear) {
        onClear();
      } else {
        onFilterChange({ 
          category: undefined, 
          subcategory: undefined, 
          minPrice: undefined, 
          maxPrice: undefined,
          bestRated: false,
          city: undefined,
          state: undefined
        });
      }
  };

  const handleBestRatedChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onFilterChange({
        category: selectedCategory,
        subcategory: selectedSubcategory,
        minPrice,
        maxPrice,
        bestRated: e.target.checked,
        city,
        state
    });
  };

  return (
    <div className="w-full h-full md:w-64 flex flex-col md:block flex-shrink-0 bg-white rounded-xl md:border md:border-gray-100 md:h-fit md:sticky md:top-20 md:p-4 shadow-sm md:shadow-none relative">
      <div className="flex-none p-4 md:p-0 flex items-center justify-between border-b border-gray-100 md:border-0 md:mb-4 bg-white">
        <h3 className="font-bold text-gray-800 text-lg md:text-base">Filtros</h3>
        <div className="flex items-center gap-4">
            <button 
                onClick={handleClearAll}
                className="text-xs text-primary hover:underline font-medium"
            >
                Limpiar todo
            </button>
            {onClose && (
                <button 
                  onClick={onClose} 
                  className="md:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-full transition-colors"
                  aria-label="Cerrar filtros"
                >
                    <X size={24} />
                </button>
            )}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto scrollbar-thin p-4 pb-24 md:p-0 md:overflow-visible md:pb-0">
        {/* Best Rated Filter */}
        <div className="mb-6">
            <h4 className="text-sm font-semibold text-gray-700 mb-3">Destacados</h4>
            <label className="flex items-center gap-2 cursor-pointer group">
            <div className="relative flex items-center">
                <input 
                type="checkbox" 
                className="peer h-4 w-4 rounded border-gray-300 text-primary focus:ring-primary/20"
                checked={bestRated || false}
                onChange={handleBestRatedChange}
                />
            </div>
            <span className="text-sm text-gray-600 group-hover:text-gray-900 transition-colors">
                Mejores calificados
            </span>
            </label>
        </div>

        {/* Price Filter */}
        <div className="mb-6">
            <h4 className="text-sm font-semibold text-gray-700 mb-3">Rango de Precio</h4>
            <div className="space-y-3">
            <div className="flex items-center gap-2">
                <div className="relative flex-1">
                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                <input
                    type="number"
                    placeholder="Min"
                    value={localMinPrice}
                    onChange={(e) => setLocalMinPrice(e.target.value)}
                    className="w-full pl-5 pr-2 py-1.5 text-sm border rounded-lg focus:outline-none focus:border-primary"
                />
                </div>
                <span className="text-gray-400">-</span>
                <div className="relative flex-1">
                <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400 text-xs">$</span>
                <input
                    type="number"
                    placeholder="Max"
                    value={localMaxPrice}
                    onChange={(e) => setLocalMaxPrice(e.target.value)}
                    className="w-full pl-5 pr-2 py-1.5 text-sm border rounded-lg focus:outline-none focus:border-primary"
                />
                </div>
            </div>
            <button
                onClick={handlePriceApply}
                className="hidden md:block w-full py-1.5 bg-primary/10 text-primary text-sm font-medium rounded-lg hover:bg-primary/20 transition-colors"
            >
                Aplicar Precio
            </button>
            </div>
        </div>

        {/* Location Filter */}
        <div className="mb-6">
            <h4 className="text-sm font-semibold text-gray-700 mb-3">Ubicación</h4>
            <div className="space-y-3">
            <SearchableSelect
                id="recommendations-state"
                value={selectedState}
                options={states}
                onChange={(option) => {
                    setSelectedState(option);
                    setSelectedCity(null);
                    setCities([]);
                }}
                placeholder={catalogLoading.states ? "Cargando estados..." : "Estado"}
                searchPlaceholder="Buscar estado..."
                disabled={catalogLoading.states}
                className="h-9 rounded-lg border-gray-200 text-sm focus:ring-primary/20"
            />
            <SearchableSelect
                id="recommendations-city"
                value={selectedCity}
                options={cities}
                onChange={setSelectedCity}
                placeholder={catalogLoading.cities ? "Cargando ciudades..." : selectedState ? "Ciudad" : "Elige un estado"}
                searchPlaceholder="Buscar ciudad..."
                disabled={!selectedState || catalogLoading.cities}
                className="h-9 rounded-lg border-gray-200 text-sm focus:ring-primary/20"
            />
            <button
                onClick={handleLocationApply}
                className="hidden md:block w-full py-1.5 bg-primary/10 text-primary text-sm font-medium rounded-lg hover:bg-primary/20 transition-colors"
            >
                Aplicar ubicación
            </button>
            </div>
        </div>

        {/* Business type filter */}
        <div className="mb-6">
            <h4 className="mb-3 text-sm font-semibold text-gray-700">Explora negocios</h4>
            <div>
                <button
                    type="button"
                    onClick={() => onBusinessTypeChange(null)}
                    className={cn(
                        "w-full border-b border-gray-50 py-2 text-left text-sm transition-colors hover:text-primary",
                        !businessTypeSlug && selectedIsDirectory === undefined ? "font-bold text-primary" : "text-gray-600",
                    )}
                >
                    Todos
                </button>
                <button
                    type="button"
                    onClick={() => onBusinessTypeChange(null, false)}
                    className={cn(
                        "w-full border-b border-gray-50 py-2 text-left text-sm transition-colors hover:text-primary",
                        selectedIsDirectory === false ? "font-bold text-primary" : "text-gray-600",
                    )}
                >
                    Tienda en línea
                </button>
                <button
                    type="button"
                    onClick={() => onBusinessTypeChange(null, true)}
                    className={cn(
                        "w-full border-b border-gray-50 py-2 text-left text-sm transition-colors hover:text-primary",
                        selectedIsDirectory === true ? "font-bold text-primary" : "text-gray-600",
                    )}
                >
                    Directorio
                </button>
                {businessTypes.map((businessType) => (
                    <button
                        key={businessType.id}
                        type="button"
                        onClick={() => onBusinessTypeChange(businessType.slug)}
                        className={cn(
                            "w-full border-b border-gray-50 py-2 text-left text-sm transition-colors last:border-0 hover:text-primary",
                            businessTypeSlug === businessType.slug ? "font-bold text-primary" : "text-gray-600",
                        )}
                    >
                        {businessType.name}
                    </button>
                ))}
            </div>
        </div>

        {/* Categories Filter */}
        <div>
            <h4 className="text-sm font-semibold text-gray-700 mb-3">Categorías</h4>
            <div className="space-y-1">
            {categories.map((category) => {
                const isSelected = selectedCategory === category.slug;
                const isExpanded = expandedCategory === category.slug || isSelected;
                const categorySubs = subcategories.filter(sub => sub.category_id === category.id);
                const hasSubs = categorySubs.length > 0;

                return (
                <div key={category.id} className="border-b border-gray-50 last:border-0 pb-1 mb-1">
                    <button
                    onClick={() => handleCategoryClick(category.slug)}
                    className={cn(
                        "flex items-center justify-between w-full py-2 text-left text-sm hover:text-primary transition-colors",
                        isSelected ? "font-bold text-primary" : "text-gray-600"
                    )}
                    >
                    <span>{category.name}</span>
                    {hasSubs && (
                        <ChevronRight
                        size={14}
                        className={cn(
                            "transition-transform",
                            isExpanded ? "rotate-90" : ""
                        )}
                        />
                    )}
                    </button>

                    {hasSubs && isExpanded && (
                    <div className="pl-3 pb-2 space-y-1">
                        {categorySubs.map((sub) => (
                        <button
                            key={sub.id}
                            onClick={(e) => handleSubcategoryClick(e, sub.slug, category.slug)}
                            className={cn(
                            "flex items-center gap-2 w-full py-1 text-xs hover:text-primary transition-colors",
                            selectedSubcategory === sub.slug
                                ? "text-primary font-medium"
                                : "text-gray-500"
                            )}
                        >
                            <div className={cn(
                                "w-3 h-3 rounded border flex items-center justify-center",
                                selectedSubcategory === sub.slug ? "border-primary bg-primary text-white" : "border-gray-300"
                            )}>
                                {selectedSubcategory === sub.slug && <Check size={8} />}
                            </div>
                            {sub.name}
                        </button>
                        ))}
                    </div>
                    )}
                </div>
                );
            })}
            </div>
        </div>
      </div>

      {onClose && (
        <div className="absolute bottom-0 left-0 w-full p-4 border-t border-gray-100 md:hidden bg-white shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-20">
            <button 
                onClick={() => {
                    handleApplyAll();
                    onClose();
                }}
                className="w-full bg-[#004e28] text-white font-bold py-3 rounded-xl hover:bg-[#003d1f] transition-colors flex items-center justify-center gap-2"
            >
                Aplicar filtros
            </button>
        </div>
      )}
    </div>
  );
}
